def transform(grid):
    h, w = len(grid), len(grid[0])
    objects = set()
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[i][j] == color
                             for i in range(r, r + 3)
                             for j in range(c, c + 3)):
                objects.add((r + 1, c + 1, color))
    out = [row[:] for row in grid]
    lines = {}
    for r, c, color in objects:
        for j in range(w):
            lines.setdefault((r, j), set()).add(color)
        for i in range(h):
            lines.setdefault((i, c), set()).add(color)
    for (r, c), colors in lines.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
